    "@types/node": "24.19.2",
    "@vitadeck/host-companion": "workspace:*",
    "@vitadeck/sdk": "workspace:*",
    "typescript": "7.0.2"
  },
  "peerDependencies": {
    "@vitadeck/sdk": "workspace:*"
  }
}
